INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter "Betrieb" von IT-Systemen?', 2, '[{"text": "Laufende Wartung und Überwachung", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Softwareentwicklung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Betrieb von IT-Systemen?', 3, '[{"text": "Hohe Verfügbarkeit sicherstellen", "correct": true, "because": "Minimiert Ausfälle"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zum Betrieb von IT-Systemen?', 5, '[{"text": "Systemüberwachung", "correct": true, "because": "Fehler früh erkennen"}, {"text": "Wartung", "correct": true, "because": "Sichert Funktion"}, {"text": "Marketing", "correct": false, "because": "Kein Betriebsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb umfasst regelmäßige Updates. b) Er ist nur für Server relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Clients betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Betrieb von IT-Systemen?', 4, '[{"text": "Systemüberwachung", "correct": false, "because": "Kernaufgabe"}, {"text": "Backup-Planung", "correct": false, "because": "Datensicherung wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Betrieb regelmäßige Backups umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz vor Datenverlust"}, {"text": "Nein", "correct": false, "because": "Teil des Betriebs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig im Betrieb zur Überwachung genutzt?', 3, '[{"text": "Nagios", "correct": true, "because": "Monitoring-Software"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Betrieb eines Servers?', 5, '[{"text": "Patch-Management", "correct": true, "because": "Sicherheitsupdates"}, {"text": "Performance-Überwachung", "correct": true, "because": "Leistung prüfen"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Betrieb sichert Systemverfügbarkeit. b) Er ist nur für Hardware nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Betrieb unwichtig?', 4, '[{"text": "Wartungspläne", "correct": false, "because": "Sichern Betrieb"}, {"text": "Monitoring", "correct": false, "because": "Fehlererkennung"}, {"text": "Farbe der Server", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss der Betrieb dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein guter Betrieb?', 4, '[{"text": "Geringere Ausfallzeiten", "correct": true, "because": "Hohe Verfügbarkeit"}, {"text": "Sicherheitsverbesserung", "correct": true, "because": "Updates und Monitoring"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Betrieb nur Hardware umfasst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software"}, {"text": "Ja", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Betrieb?', 3, '[{"text": "Systemstabilität", "correct": true, "because": "Hauptziel"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb umfasst Monitoring. b) Er ist nur für große Firmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechter Betrieb?', 5, '[{"text": "Häufige Ausfälle", "correct": true, "because": "Keine Wartung"}, {"text": "Datenverlust", "correct": true, "because": "Keine Backups"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker im Betrieb?', 3, '[{"text": "Systeme überwachen", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb automatisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Monitoring-Tools"}, {"text": "Nein", "correct": false, "because": "Automatisierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker im Betrieb nutzen?', 4, '[{"text": "Zabbix", "correct": true, "because": "Monitoring-Tool"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
